// n8n Code node — "Build Alert Emails"
// Fired by Simple HRIS the moment a one-off Urgent Payment request is filed
// from the People tab and lands in Payment Dispatch → Urgent. Fans out ONE
// item per watcher, each carrying a ready-to-send red-alarm HTML email telling
// them to open the HRIS and dispatch the payment.
//
// Recipients, subject and body are FIXED here (code-owned) — the caller can
// only say WHAT was filed, never who gets emailed or what the email says, so
// this endpoint can't be turned into an arbitrary-content mailer.
//
// Expected payload (n8n may nest the POST body under `.body`):
//   {
//     "event": "urgent_payment.requested",
//     "full_name": "Juan Dela Cruz",
//     "work_email": "juan@simple.biz",
//     "department": "sales",            // optional
//     "amount_php": 12345.67,            // optional in the email, shown if present
//     "note": "Advance for ...",        // optional
//     "requested_by": "Kane R"          // optional
//   }

const RECIPIENTS = [
  'carla@simple.biz',
  'claire@simple.biz',
  'lennyt@simple.biz',
];

const HRIS_LINK = 'https://simple-hris.vercel.app/';
const LOGO = 'https://simple-hris.vercel.app/simple-logo.png';

// --- OPTIONAL shared-secret gate (matches the other Simple HRIS webhooks) ---
// Leave '' to accept any caller. To lock it down: put a long random string
// here AND set the same value in the HRIS env var N8N_URGENT_PAYMENT_NOTIFY_SECRET,
// so the server sends it as the 'x-webhook-secret' header.
const REQUIRED_SECRET = '';

const root = (items[0] && items[0].json) || {};
const body = (root && typeof root.body === 'object' && root.body) ? root.body : root;
const headers = (root && typeof root.headers === 'object' && root.headers) ? root.headers : {};

const providedSecret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || body.secret || '';
if (REQUIRED_SECRET && providedSecret !== REQUIRED_SECRET) {
  throw new Error('Unauthorized: missing or invalid webhook secret.');
}

function esc(v) {
  if (v == null) return '';
  return String(v)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}
function money(v) {
  const n = typeof v === 'string' ? parseFloat(v) : v;
  if (n == null || !isFinite(n) || n <= 0) return '';
  return '\u20B1' + n.toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

const fullName = esc(body.full_name || '').trim() || 'Someone';
const workEmail = esc(body.work_email || '');
const dept = esc(body.department || '');
const amount = esc(money(body.amount_php));
const note = esc(body.note || '');
const requestedBy = esc(body.requested_by || '');

const SUBJECT = '\uD83D\uDEA8 Urgent Payment filed \u2014 someone needs paying, check the HRIS';

function detailRow(label, value) {
  if (!value) return '';
  return '<tr>' +
    '<td style="padding:8px 14px;font-size:12px;color:#71717a;white-space:nowrap;vertical-align:top;border-bottom:1px solid #f4f4f5">' + label + '</td>' +
    '<td style="padding:8px 14px;font-size:13px;color:#18181b;font-weight:bold;border-bottom:1px solid #f4f4f5">' + value + '</td>' +
  '</tr>';
}

// Bulletproof CTA button — VML roundrect for Outlook, padded inline-block <a>
// for every other client.
function ctaButton() {
  return '' +
    '<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:4px 0 6px"><tr><td>' +
      '<!--[if mso]><v:roundrect xmlns:v="urn:schemas-microsoft-com:vml" xmlns:w="urn:schemas-microsoft-com:office:word" href="' + HRIS_LINK + '" style="height:48px;v-text-anchor:middle;width:280px;" arcsize="21%" strokecolor="#dc2626" fillcolor="#dc2626"><w:anchorlock/><center style="color:#ffffff;font-family:Arial,sans-serif;font-size:15px;font-weight:bold;">Open HRIS &rarr; Payment Dispatch</center></v:roundrect><![endif]-->' +
      '<!--[if !mso]><!-- --><a href="' + HRIS_LINK + '" style="display:inline-block;background:#dc2626;color:#ffffff;font-size:15px;font-weight:bold;text-decoration:none;padding:14px 28px;border-radius:10px">Open HRIS &rarr; Payment Dispatch</a><!--<![endif]-->' +
    '</td></tr></table>';
}

function renderHtml() {
  const details =
    detailRow('Who to pay', fullName + (workEmail ? ' &middot; <span style="font-weight:normal;color:#52525b">' + workEmail + '</span>' : '')) +
    detailRow('Amount', amount) +
    detailRow('Department', dept) +
    detailRow('Note', note) +
    detailRow('Filed by', requestedBy);
  return '' +
    '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Urgent Payment filed</title></head>' +
    '<body style="margin:0;background:#f4f4f5;padding:24px 12px;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#18181b">' +
      '<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:transparent;font-size:1px;line-height:1px">' + fullName + ' needs an urgent one-off payment &mdash; it is waiting in Payment Dispatch &rarr; Urgent.</div>' +
      '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f5"><tr><td align="center">' +
        '<table role="presentation" width="520" cellpadding="0" cellspacing="0" style="width:100%;max-width:520px;background:#ffffff;border:1px solid #e4e4e7;border-radius:14px;overflow:hidden;box-shadow:0 6px 24px rgba(220,38,38,0.10)">' +
          '<tr><td style="padding:18px 26px 12px"><img src="' + LOGO + '" alt="Simple" width="88" height="30" style="display:block;border:0;height:30px;width:88px"></td></tr>' +
          '<tr><td bgcolor="#0a0a0b" style="background:#0a0a0b;padding:22px 26px;border-bottom:4px solid #dc2626">' +
            '<span style="display:inline-block;background:#dc2626;color:#ffffff;font-size:11px;font-weight:bold;letter-spacing:1.5px;text-transform:uppercase;padding:5px 12px;border-radius:999px">&#128680; Urgent payment</span>' +
            '<div style="margin-top:14px;font-size:22px;line-height:1.3;color:#ffffff;font-weight:bold">Someone needs an urgent payment</div>' +
            '<div style="margin-top:6px;font-size:13px;color:#d4d4d8">A one-off payment request just landed in Payment Dispatch &rarr; Urgent.</div>' +
          '</td></tr>' +
          '<tr><td style="padding:22px 26px 4px">' +
            '<p style="margin:0 0 14px;font-size:15px;color:#18181b">Hi,</p>' +
            '<p style="margin:0 0 16px;font-size:14px;line-height:1.6;color:#3f3f46">An <strong>Urgent Payment</strong> was just filed in the HRIS and is waiting to be dispatched. Please open <strong>Payment Dispatch &rarr; Urgent</strong> and send it as soon as you can.</p>' +
            (details ? '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#fef2f2;border:1px solid #fecaca;border-radius:10px;margin:0 0 18px;overflow:hidden">' + details + '</table>' : '') +
            ctaButton() +
            '<p style="margin:10px 0 18px;font-size:12px;color:#71717a;word-break:break-all">Button not working? Copy and paste this link:<br><a href="' + HRIS_LINK + '" style="color:#dc2626">' + esc(HRIS_LINK) + '</a></p>' +
          '</td></tr>' +
          '<tr><td style="padding:16px 26px 20px;border-top:1px solid #f4f4f5"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="font-size:12px;color:#52525b;font-weight:bold">Simple &middot; Confidential</td><td align="right" style="font-size:11px;color:#71717a">Automated alert from Simple HRIS</td></tr></table></td></tr>' +
        '</table>' +
        '<div style="max-width:520px;margin:12px auto 0;font-size:11px;color:#71717a;text-align:center;line-height:1.5">You are receiving this because you handle Payment Dispatch in the Simple HRIS.</div>' +
      '</td></tr></table>' +
    '</body></html>';
}

const html = renderHtml();
return RECIPIENTS.map(function (email) {
  return { json: { to: email, subject: SUBJECT, html: html } };
});
